const readUiState=(key:string)=>{try{return localStorage.getItem(`studio.ui.${key}`)}catch{return null}};
const readUiId=(key:string)=>{const value=Number(readUiState(key));return Number.isSafeInteger(value)&&value>0?value:null};
const date=(n:number|null)=>n?new Date(n*1000).toLocaleDateString(): 'Never';
const short=(s:string|null)=>s?s.slice(0,12):'—';
const formatBytes=(n:number|null)=>n===null?'Unmeasured':n>=1024**3?`${(n/1024**3).toFixed(1)} GB`:n>=1024**2?`${(n/1024**2).toFixed(0)} MB`:`${n} B`;
const buildStageActive=(phase:string,label:string)=>{const value=phase.toLowerCase(),stage=label.toLowerCase();if(stage.includes('fetch'))return value.includes('fetch')||value.includes('preparing repository');if(stage.includes('submodule'))return value.includes('submodule');if(stage.includes('dependenc'))return value.includes('dependenc');if(stage.includes('cmake')||stage.includes('configur'))return value.includes('configure');if(stage.includes('compile')||stage.includes('ninja'))return value.includes('compile');if(stage.includes('install'))return value.includes('install');if(stage.includes('validat'))return value.includes('validat');if(stage.includes('applying'))return value.includes('applying');return false};
function logDiagnosis(log:string){
 if(/Unhandled host exception/i.test(log))return 'The emulator exited after an unhandled host exception. The log contains guest fault context; it does not establish whether the game is playable or identify one definitive cause.';
 if(/Unresolved import stub called/i.test(log))return 'The emulator reported unresolved import stubs. Their role in this session outcome is unknown.';
 if(/error while loading shared libraries|undefined symbol/i.test(log))return 'The emulator reported a host library loading or symbol error. Review the technical log below.';
 return null;
}
function logLineLevel(line:string):'Info'|'Warning'|'Error'|'Debug'{
 if(/\b(debug|trace)\b/i.test(line))return 'Debug';
 if(/\b(warn|warning)\b/i.test(line))return 'Warning';
 if(/\b(error|exception|fault|crash|unresolved|failed|fatal)\b/i.test(line))return 'Error';
 return 'Info';
}
const gameIconCache=new Map<number,string|null>();
function GameCard({game,selected,onSelect}:{game:Game;selected:boolean;onSelect:()=>void}){
 const element=useRef<HTMLButtonElement>(null);const [icon,setIcon]=useState<string|null>(null);
 useEffect(()=>{let disposed=false;const load=()=>{if(gameIconCache.has(game.id)){if(!disposed)setIcon(gameIconCache.get(game.id)!);return}invoke<number[]|null>('read_game_icon',{gameId:game.id}).then(bytes=>{const url=bytes?URL.createObjectURL(new Blob([new Uint8Array(bytes)],{type:'image/png'})):null;gameIconCache.set(game.id,url);if(!disposed)setIcon(url)}).catch(()=>gameIconCache.set(game.id,null))};const target=element.current;if(!target)return;if(typeof IntersectionObserver==='undefined'){load();return()=>{disposed=true}}const observer=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)){observer.disconnect();load()}},{rootMargin:'180px'});observer.observe(target);return()=>{disposed=true;observer.disconnect()}},[game.id]);
 return <button ref={element} data-game-id={game.id} className={'game-card '+(selected?'selected':'')} onClick={onSelect}><div className="game-art">{icon?<img loading="lazy" src={icon} alt={`${game.title} icon`}/>:<Gamepad2/>}</div><strong>{game.title}</strong><small>{game.last_played?`Played ${date(game.last_played)}`:'Not played yet'}</small></button>
}
function HomeGameTile({game,selected,onSelect}:{game:Game;selected:boolean;onSelect:()=>void}){
 const [icon,setIcon]=useState<string|null>(null);
 useEffect(()=>{let url:string|undefined;let disposed=false;invoke<number[]|null>('read_game_icon',{gameId:game.id}).then(bytes=>{if(!bytes||disposed)return;url=URL.createObjectURL(new Blob([new Uint8Array(bytes)],{type:'image/png'}));setIcon(url)}).catch(()=>{});return()=>{disposed=true;if(url)URL.revokeObjectURL(url)}},[game.id]);
 return <button className={`home-game-tile ${selected?'selected':''}`} onClick={onSelect} aria-pressed={selected}><span className="home-game-art">{icon?<img src={icon} alt="" loading="lazy"/>:<Gamepad2 size={25}/>}</span><strong title={game.title}>{game.title}</strong></button>
}
function VirtualGameGrid({games,selectedId,onSelect}:{games:Game[];selectedId:number|undefined;onSelect:(id:number)=>void}){
 const grid=useRef<HTMLDivElement>(null);const [viewport,setViewport]=useState({width:0,height:0,top:0});
 useEffect(()=>{const element=grid.current;if(!element)return;const measure=()=>setViewport(current=>({...current,width:element.clientWidth,height:element.clientHeight,top:element.scrollTop}));measure();const observer=new ResizeObserver(measure);observer.observe(element);return()=>observer.disconnect()},[]);
 useEffect(()=>{if(grid.current)grid.current.scrollTop=0;setViewport(current=>current.top===0?current:{...current,top:0})},[games]);
 const columns=Math.max(1,Math.floor((viewport.width+17)/177));const rowHeight=274;const totalRows=Math.ceil(games.length/columns);const firstRow=Math.max(0,Math.floor(viewport.top/rowHeight)-2);const rowCount=Math.ceil(viewport.height/rowHeight)+4;const endRow=Math.min(totalRows,firstRow+rowCount);const visible=games.slice(firstRow*columns,endRow*columns);
 const gamepadFocus=useRef(false);
 useEffect(()=>{const move=(event:Event)=>{const detail=(event as CustomEvent<{direction:string;gameId:number}>).detail;const direction=detail?.direction;if(!['left','right','up','down'].includes(direction))return;const selectedIndex=games.findIndex(game=>game.id===(detail.gameId||selectedId));const index=selectedIndex>=0?selectedIndex:games.findIndex(game=>game.id===selectedId);const next=index<0?0:index+(direction==='left'?-1:direction==='right'?1:direction==='up'?-columns:columns);if(next<0||next>=games.length)return;gamepadFocus.current=true;const target=games[next];if(grid.current)grid.current.scrollTop=Math.max(0,Math.floor(next/columns)*rowHeight-2*rowHeight);onSelect(target.id)};window.addEventListener('studio:gamepad-move',move);return()=>window.removeEventListener('studio:gamepad-move',move)},[games,selectedId,columns]);
 useEffect(()=>{if(!gamepadFocus.current||selectedId===undefined)return;const target=grid.current?.querySelector<HTMLButtonElement>(`[data-game-id="${selectedId}"]`);if(target){target.focus({preventScroll:true});gamepadFocus.current=false}},[selectedId,viewport.top,visible]);
 return <div ref={grid} className="game-grid" onScroll={event=>{const top=event.currentTarget.scrollTop;setViewport(current=>Math.floor(top/rowHeight)===Math.floor(current.top/rowHeight)?current:{...current,top})}} style={{gridTemplateColumns:`repeat(${columns},minmax(0,1fr))`}}>{firstRow>0&&<div aria-hidden="true" className="virtual-spacer" style={{gridColumn:'1 / -1',height:firstRow*rowHeight-17}}/>}{visible.map(game=><GameCard key={game.id} game={game} selected={selectedId===game.id} onSelect={()=>onSelect(game.id)}/>)}{endRow<totalRows&&<div aria-hidden="true" className="virtual-spacer" style={{gridColumn:'1 / -1',height:(totalRows-endRow)*rowHeight-17}}/>}</div>
}
