 useEffect(()=>{for(const [key,value] of [['page',page],['repository',selectedRepo?.toString()||''],['game',selectedGame?.toString()||''],['query',query],['home_game',homeSelection?.toString()||''],['build_mode',buildMode],['specs',specsOpen?'open':'closed']] as const){try{localStorage.setItem(`studio.ui.${key}`,value)}catch{break}}},[page,selectedRepo,selectedGame,query,homeSelection,buildMode,specsOpen]);
 const refresh=async()=>{const [r,b,g,s,ss]=await Promise.all([call<Repo[]>('list_repos'),call<Build[]>('list_builds'),call<Game[]>('list_games'),call<System>('system_info'),call<Session[]>('recent_sessions')]);setRepos(r);setBuilds(b);setGames(g);setSystem(s);setSessions(ss);};
