 const active=builds.find(b=>b.active);const currentGame=games.find(g=>g.id===selectedGame)||games[0];const featuredGame=useMemo(()=>games.find(game=>game.id===homeSelection)||([...games].sort((a,b)=>(b.last_played??0)-(a.last_played??0))[0]??null),[games,homeSelection]);const filteredGames=useMemo(()=>games.filter(g=>g.title.toLowerCase().includes(query.toLowerCase())),[games,query]);
 const hasUnsupportedProfile=!!profileCapabilities&&((profile.screen_width!==null&&!profileCapabilities.screen_width)||(profile.screen_height!==null&&!profileCapabilities.screen_height)||(profile.present_mode!==null&&!profileCapabilities.present_mode)||(profile.perf_overlay&&!profileCapabilities.perf_overlay)||(profile.fullscreen&&!profileCapabilities.fullscreen)||(profile.controller_color!==null&&!profileCapabilities.controller_color)||(profile.controller_volume!==null&&!profileCapabilities.controller_volume)||(profile.controller_vibration!==null&&!profileCapabilities.controller_vibration)||(profile.keyboard_player!==null&&!profileCapabilities.keyboard_player));
