 useEffect(()=>{let url:string|undefined;setFeaturedBackground(null);if(page==='home'&&featuredGame)invoke<number[]|null>('read_game_background',{gameId:featuredGame.id}).then(bytes=>{if(bytes){url=URL.createObjectURL(new Blob([new Uint8Array(bytes)],{type:'image/png'}));setFeaturedBackground(url)}}).catch(()=>{});return()=>{if(url)URL.revokeObjectURL(url)}},[featuredGame?.id,page]);
 const choose=async(kind:'file'|'directory')=>{const chosen=await open({directory:kind==='directory',multiple:false});if(typeof chosen==='string')action(async()=>{if(kind==='directory'){const n=await call<number>('scan_games',{path:chosen});setMessage(`${n} game paths found`)}else{await call('add_game',{path:chosen})}})};
